"use client"

import { Building2, Link2, GraduationCap, Clock, Car } from "lucide-react"
import type { LucideIcon } from "lucide-react"

/**
 * Client logos. These are editable placeholder wordmarks.
 * To use a real logo, drop an SVG/PNG in /public/logos and swap the
 * <span> block for <img src="/logos/your-file.svg" alt="Client" />.
 */
type Client = { name: string; sub?: string; icon: LucideIcon }

const clients: Client[] = [
  { name: "AHM Developers", icon: Building2 },
  { name: "Property Linkers", icon: Link2 },
  { name: "Education Links", icon: GraduationCap },
  { name: "Times Consultant", icon: Clock },
  { name: "FastAxi", sub: "UK", icon: Car },
]

function LogoMark({ c }: { c: Client }) {
  const Icon = c.icon
  return (
    <span className="inline-flex select-none items-center gap-2.5 whitespace-nowrap opacity-60 grayscale transition-all duration-300 hover:opacity-100 hover:grayscale-0">
      <Icon className="h-5 w-5 text-brand-purple" />
      <span className="text-lg font-bold tracking-tight text-foreground">
        {c.name}
        {c.sub && <span className="ml-1 text-brand-cyan">{c.sub}</span>}
      </span>
    </span>
  )
}

export function Marquee() {
  return (
    <section className="border-y border-border bg-secondary/40 py-10">
      <p className="mb-8 text-center text-xs font-semibold uppercase tracking-[0.25em] text-muted-foreground">
        Trusted by teams from seed to Series C
      </p>

      {/* Continuous marquee on every screen size */}
      <div className="group relative overflow-hidden [mask-image:linear-gradient(to_right,transparent,black_10%,black_90%,transparent)]">
        <div className="animate-marquee flex w-max items-center gap-16 pr-16 group-hover:[animation-play-state:paused]">
          {[...clients, ...clients, ...clients, ...clients].map((c, i) => (
            <LogoMark key={i} c={c} />
          ))}
        </div>
      </div>
    </section>
  )
}
